draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // brain
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2 + 100 + 50 * Math.sin(t), H/2, 30, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();

  // eye
  ctx.beginPath();
  ctx.arc(W/2 - 20, H/2 - 20, 10, 0, 2 * Math.PI);
  ctx.lineWidth = 3;
  ctx.stroke();

  // pupil
  ctx.beginPath();
  ctx.arc(W/2 - 20 + 5 * Math.sin(t), H/2 - 20, 5, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();

  ctx.restore();
}
